window.COURSES = window.COURSES || []; window.TIPS = window.TIPS || [];
window.COURSES.push(
{ id:"he01", cat:"health", e:"😴", title:"Sleep Foundations", sub:"Build nights that actually restore you", cards:[
 {e:"🌙", h:"Why sleep matters", t:"Sleep is when your brain consolidates memory and your body repairs tissue. Short sleep over time is linked with worse mood, focus, appetite control and long-term health. Treat it as a daily health habit, not a luxury.", stat:{n:"7-9 h", l:"typical adult sleep need per night"}},
 {e:"⏰", h:"Keep a steady schedule", t:"Going to bed and waking at similar times, even on weekends, anchors your body clock. Aim to keep your wake time within about an hour every day. Consistency often helps more than adding one extra hour on a single night."},
 {e:"☀️", h:"Get morning light", t:"Bright light soon after waking tells your brain it is daytime and helps set your body clock. Step outside for 10 to 20 minutes, even on a cloudy day, which is still far brighter than indoor lighting."},
 {e:"🌡️", h:"Cool, dark, quiet room", t:"Most people sleep better in a cool, dark, quiet bedroom. Try a temperature around 16 to 19 C (60 to 67 F), blackout curtains or a mask, and earplugs or white noise if you live somewhere loud.", stat:{n:"16-19 C", l:"commonly suggested bedroom temperature range"}},
 {e:"☕", h:"Mind caffeine timing", t:"Caffeine has a half-life of roughly five to six hours, so an afternoon coffee can still be active at bedtime. Many people sleep better by stopping caffeine about eight hours before bed. Test what works for you."},
 {e:"📱", h:"Wind down your evening", t:"Give your brain a runway before bed. Dim the lights, put screens away or lower the brightness, and do something calm. The content and stimulation of your phone often matter as much as the light itself.", list:["Dim lights 1 hour before bed","Keep phone out of reach","Read, stretch or take a warm shower","Write tomorrow's to-do list"]},
 {e:"🛏️", h:"Reserve bed for sleep", t:"If you lie awake for what feels like 20 minutes or more, get up, do something quiet in dim light, and return when sleepy. This helps your brain link the bed with sleeping rather than frustration."},
 {e:"🩺", h:"When to get help", t:"Occasional bad nights are normal. If you regularly struggle to sleep, snore loudly, gasp at night, or feel exhausted despite enough hours, talk to a doctor. Sleep problems are common and often treatable."}
], quiz:[
 {q:"What is the typical sleep range recommended for most adults?", o:["4-5 hours","7-9 hours","10-12 hours"], a:1, w:"Most adults function best with roughly 7 to 9 hours per night."},
 {q:"Which habit helps set your body clock most reliably?", o:["Sleeping in on weekends","Using a screen in bed","A consistent wake time and morning light"], a:2, w:"Regular timing plus morning light anchors your circadian rhythm."},
 {q:"If you cannot sleep after about 20 minutes, what is a good move?", o:["Get up and do something calm in dim light","Check your phone in bed","Drink a coffee"], a:0, w:"Leaving bed keeps it associated with sleep rather than wakefulness."},
 {q:"Why can late-afternoon coffee hurt sleep?", o:["It dehydrates you overnight","It is still partly active at bedtime","It lowers body temperature"], a:1, w:"Caffeine's half-life of several hours means some remains in your system at night."}
]},
{ id:"he02", cat:"health", e:"🥗", title:"Nutrition Basics", sub:"Eat well without the complexity", cards:[
 {e:"🍽️", h:"Focus on whole foods", t:"Most healthy eating patterns share one trait: they are built mostly on minimally processed foods like vegetables, fruit, beans, whole grains, fish, eggs, nuts and lean meats. You do not need perfection, just a solid majority."},
 {e:"🥦", h:"Fill half your plate", t:"A simple visual guide: fill about half your plate with vegetables and fruit, a quarter with protein, and a quarter with whole grains or starchy foods. Add a little healthy fat. No weighing or counting needed.", list:["Half: vegetables and fruit","Quarter: protein","Quarter: whole grains or potatoes","Add a thumb of healthy fat"]},
 {e:"🌾", h:"Fibre is underrated", t:"Fibre supports digestion, helps you feel full and is linked with better heart health. Most adults eat less than recommended. Beans, lentils, oats, vegetables, fruit and whole grains are easy, affordable sources.", stat:{n:"25-38 g", l:"common daily fibre targets for adults"}},
 {e:"🫒", h:"Choose healthier fats", t:"Fats from olive oil, nuts, seeds and fish like salmon are linked with better heart health than large amounts of saturated fat from processed meats and pastries. You need some fat, so aim for quality rather than zero."},
 {e:"🍬", h:"Watch added sugar", t:"Sugar naturally in fruit comes with fibre and water. Added sugar in soda, sweets and many sauces is easy to overeat. Health bodies generally suggest keeping added sugar to a small share of daily calories.", stat:{n:"<10%", l:"of calories from added sugar is a common guideline"}},
 {e:"🏷️", h:"Read labels smartly", t:"Check the ingredient list and the per-100g column rather than the front-of-pack claims. Shorter ingredient lists with recognisable foods are usually a good sign. Compare similar products for sugar, salt and fibre."},
 {e:"🧂", h:"Moderate your salt", t:"Most dietary salt comes from packaged and restaurant food, not the shaker. Cooking more at home and rinsing canned beans can help. If you have blood pressure concerns, ask a doctor what level suits you."},
 {e:"⚖️", h:"Aim for the 80 percent", t:"Eating well most of the time beats strict rules you cannot sustain. A treat at a celebration does not undo your health. Build a pattern you can enjoy for years, not a punishing short-term plan."}
], quiz:[
 {q:"Which plate split is a simple, balanced guide?", o:["Half vegetables and fruit","Half pasta","Half dessert"], a:0, w:"Filling about half the plate with produce raises fibre and nutrient intake."},
 {q:"Where does most dietary salt usually come from?", o:["The salt shaker at home","Packaged and restaurant food","Fresh vegetables"], a:1, w:"Processed and restaurant foods contribute the majority of salt for most people."},
 {q:"What is a common guideline for added sugar?", o:["Zero grams ever","Under about 10% of daily calories","Half your calories"], a:1, w:"Many health bodies suggest keeping added sugar under around 10% of calories."},
 {q:"Which approach tends to work best long term?", o:["Strict rules with no flexibility","Eating well most of the time","Skipping meals daily"], a:1, w:"Sustainable, flexible habits beat rigid plans that people abandon."}
]},
{ id:"he03", cat:"health", e:"🍗", title:"Protein Made Simple", sub:"How much, when and from where", cards:[
 {e:"💪", h:"What protein does", t:"Protein supplies amino acids your body uses to build and repair muscle, enzymes, skin and immune cells. It also helps you feel full after meals, which can make healthy eating easier to sustain."},
 {e:"🧮", h:"Baseline needs", t:"The standard minimum for healthy adults is about 0.8 g per kg of body weight daily. People who lift weights or are older are often advised to aim higher. A doctor or dietitian can tailor this, especially with kidney issues.", stat:{n:"0.8 g/kg", l:"baseline daily protein for most adults"}},
 {e:"🏋️", h:"If you train", t:"Research on strength training suggests roughly 1.2 to 2.0 g per kg per day supports muscle growth for most active people. More than that rarely adds benefit. Check with a professional if you have health conditions.", stat:{n:"1.2-2 g/kg", l:"commonly studied range for active people"}},
 {e:"🍳", h:"Spread it across meals", t:"Aim for a solid serving of protein at each meal, around 20 to 40 grams, rather than saving it all for dinner. Spreading intake is a simple way to hit your total and keep hunger steady.", list:["Eggs or yogurt at breakfast","Beans, fish or chicken at lunch","Tofu, lean meat or lentils at dinner","Cheese or nuts for snacks"]},
 {e:"🐟", h:"Animal sources", t:"Fish, eggs, dairy, poultry and lean meat are complete proteins with all essential amino acids. Fatty fish adds omega-3 fats. Limit processed meats such as bacon and sausages, which are linked with higher health risks."},
 {e:"🌱", h:"Plant sources work too", t:"Beans, lentils, tofu, tempeh, edamame, nuts, seeds and whole grains provide plenty of protein. Eating a variety through the day covers all essential amino acids, so you do not need to combine them in every meal."},
 {e:"🥤", h:"Powders are optional", t:"Protein powder is just convenient food. If whole foods already get you to your target, you do not need it. If it helps you fit protein into a busy day, choose a plain, reputable product and treat it as a snack."},
 {e:"🩺", h:"Know your limits", t:"For healthy people, higher protein intakes within typical ranges are generally considered safe. If you have kidney disease or another medical condition, talk to a doctor before raising your intake."}
], quiz:[
 {q:"What is the standard baseline protein intake for healthy adults?", o:["About 0.8 g per kg","About 3 g per kg","About 5 g per kg"], a:0, w:"0.8 g/kg is the commonly cited minimum for healthy adults."},
 {q:"How is protein often best distributed?", o:["All at dinner","Across all meals","Only after workouts"], a:1, w:"A serving at each meal helps meet totals and supports fullness."},
 {q:"Do you need protein powder to build muscle?", o:["Yes, always","No, whole foods can do the job","Only if you are over 30"], a:1, w:"Powders are convenient but not required if food covers your target."},
 {q:"Who should check with a doctor before raising protein a lot?", o:["Anyone with kidney disease","Only teenagers","Nobody"], a:0, w:"People with kidney conditions may need individual guidance."}
]},
{ id:"he04", cat:"health", e:"💧", title:"Hydration Done Right", sub:"Drink enough, skip the hype", cards:[
 {e:"🚰", h:"Why water matters", t:"Water supports temperature control, digestion, joint lubrication and blood volume. Even mild dehydration can reduce concentration and make you feel tired or headachy. Most of the time, thirst is a reliable guide."},
 {e:"🔢", h:"How much is enough?", t:"Needs vary with size, climate, activity and diet. A common guide is around 2 to 3 litres of total fluids daily, and some of that comes from food and other drinks. You do not need to hit an exact number.", stat:{n:"2-3 L", l:"common total daily fluid range, including food"}},
 {e:"🟡", h:"Check your urine colour", t:"Pale straw yellow usually suggests good hydration. Dark amber suggests you should drink more. Some vitamins and foods change colour, so use it as a rough guide. Persistent changes are worth mentioning to a doctor."},
 {e:"🍵", h:"Other drinks count", t:"Tea, coffee, milk and sparkling water all contribute to hydration. Moderate caffeine does not meaningfully dehydrate regular drinkers. Fruit, vegetables and soups also add significant water to your day."},
 {e:"🏃", h:"Drink around exercise", t:"For most workouts under an hour, drinking to thirst is enough. For long or hot sessions, sip regularly and consider adding sodium. Sweat rates differ a lot, so weighing before and after can show your own needs."},
 {e:"⛔", h:"Overhydration exists", t:"Drinking very large volumes in a short time can dilute blood sodium, a rare but serious problem called hyponatremia, mostly seen in endurance events. Sip steadily rather than forcing water beyond thirst."},
 {e:"🧊", h:"Make it easy", t:"Habit beats willpower. Keep a bottle you like within reach and tie drinking to routines. Flavour with lemon, cucumber or mint if plain water bores you.", list:["Glass of water on waking","Bottle at your desk","Glass with each meal","Sip before and after exercise"]},
 {e:"🩺", h:"When thirst is unusual", t:"Constant extreme thirst, very frequent urination, or being unable to keep fluids down can signal a medical issue. Do not self-diagnose; speak to a doctor if it persists. Older adults may feel thirst less and need reminders."}
], quiz:[
 {q:"What urine colour usually suggests good hydration?", o:["Dark amber","Pale straw yellow","Bright neon"], a:1, w:"Pale yellow generally indicates adequate hydration."},
 {q:"Do tea and coffee count toward fluid intake?", o:["No, never","Yes, they contribute","Only if decaf"], a:1, w:"Caffeinated drinks hydrate in typical amounts for regular drinkers."},
 {q:"For a short workout, what is usually enough?", o:["Drinking to thirst","Drinking 3 litres","Fasting from water"], a:0, w:"Thirst is a reliable guide for most workouts under an hour."},
 {q:"What is the risk of drinking huge amounts rapidly?", o:["Hyponatremia","Gaining muscle","Better sleep"], a:0, w:"Excess water can dilute blood sodium to dangerous levels."}
]},
{ id:"he05", cat:"health", e:"🏋️", title:"Strength Training Starter", sub:"Build muscle and bone, safely", cards:[
 {e:"💪", h:"Why lift weights", t:"Strength training builds muscle, strengthens bones and tendons, improves balance and supports blood sugar control. Muscle mass declines with age unless you challenge it, so lifting is one of the best long-term health investments.", stat:{n:"2x/week", l:"muscle-strengthening sessions commonly recommended"}},
 {e:"🔁", h:"Learn the main patterns", t:"You do not need dozens of exercises. Cover the basic movements: squat, hinge, push, pull and carry. A handful of exercises done well builds a strong foundation.", list:["Squat or leg press","Hip hinge or deadlift variation","Push-up or press","Row or pull-down"]},
 {e:"📏", h:"Form before weight", t:"Start light enough that you can control every rep and keep good posture. Add weight only when form stays solid. A session with a qualified coach early on can prevent bad habits and injuries."},
 {e:"📈", h:"Progressive overload", t:"Muscles grow when asked to do slightly more over time. Add a rep, a small amount of weight, or an extra set each week or two. Tracking your workouts makes steady progress easy to see."},
 {e:"🔢", h:"Sets and reps", t:"A practical starting point is 2 to 3 sets of 6 to 12 reps per exercise, finishing with a couple of reps still in the tank. You do not need to train to failure to see results."},
 {e:"🛌", h:"Recovery builds muscle", t:"Muscle is built during rest, not in the gym. Leave at least a day between hard sessions for the same muscle group, sleep well and eat enough protein. Persistent soreness or fatigue means you may need more rest."},
 {e:"🔥", h:"Warm up first", t:"Spend five to ten minutes on light movement and a few lighter practice sets of your first exercise. This raises temperature, rehearses the pattern and makes the working sets feel better and safer."},
 {e:"🩺", h:"Start smart", t:"If you are new to exercise, have a chronic condition, are pregnant or recovering from injury, check with a doctor first. Sharp pain is a stop signal. Mild muscle soreness the next day is normal."}
], quiz:[
 {q:"How often are muscle-strengthening sessions commonly recommended?", o:["Never","About twice a week","Every hour"], a:1, w:"Health guidelines usually recommend at least two sessions weekly."},
 {q:"What does progressive overload mean?", o:["Gradually asking your muscles to do more","Lifting maximum weight daily","Never changing your routine"], a:0, w:"Small increases over time drive adaptation."},
 {q:"What should you prioritise when starting?", o:["Heaviest weight possible","Good form","Training to failure"], a:1, w:"Controlled technique protects joints and builds a base."},
 {q:"When is muscle actually built?", o:["During the set","During recovery","Only while stretching"], a:1, w:"Adaptation happens during rest, supported by sleep and food."}
]},
{ id:"he06", cat:"health", e:"🚶", title:"Cardio and Walking", sub:"Move your heart in easy ways", cards:[
 {e:"❤️", h:"Why cardio counts", t:"Regular aerobic activity strengthens your heart, improves circulation, supports mood and lowers risk of many chronic conditions. You can start with very little and still gain benefits.", stat:{n:"150 min", l:"moderate activity per week is a common guideline"}},
 {e:"🚶‍♀️", h:"Walking is powerful", t:"Walking needs no equipment and is gentle on joints. Studies link daily walking with lower risk of early death, with benefits showing up well below 10,000 steps for many people.", stat:{n:"7,000+", l:"daily steps linked with strong benefits in studies"}},
 {e:"🗣️", h:"The talk test", t:"Moderate intensity means you can talk but not sing. Vigorous means you can only say a few words. This simple test works without a heart rate monitor and fits most people."},
 {e:"📅", h:"Build the habit slowly", t:"If you are inactive, add 5 to 10 minutes a day and grow gradually. A small habit you keep beats an ambitious plan you drop. Consistency over weeks matters more than any single workout."},
 {e:"⚡", h:"Try some intervals", t:"Short bursts of harder effort followed by easy recovery can improve fitness in less time. Try 30 seconds brisk, 90 seconds easy, repeated for a few rounds. Beginners should build a base first and check with a doctor if unsure."},
 {e:"🧩", h:"Sneak in movement", t:"Break up long sitting with short walks. Standing, stretching or a brisk two-minute stroll each hour supports circulation and energy. Small bouts add up across the day.", list:["Walk during phone calls","Take stairs when practical","Park a bit farther away","Walk after meals"]},
 {e:"🍽️", h:"Walk after eating", t:"A gentle 10 to 15 minute walk after meals can help moderate blood sugar rises. It is also a pleasant way to digest and clear your head, with almost no downside."},
 {e:"🩺", h:"Know the warning signs", t:"Stop and seek medical help if you feel chest pain, severe breathlessness, dizziness or fainting during activity. If you have heart conditions or have been inactive and are older, ask a doctor before starting hard training."}
], quiz:[
 {q:"What is the common weekly moderate activity guideline?", o:["30 minutes","150 minutes","600 minutes"], a:1, w:"About 150 minutes of moderate activity per week is widely recommended."},
 {q:"What does the talk test measure?", o:["Intensity","Calories burned","Muscle size"], a:0, w:"Being able to talk but not sing indicates moderate effort."},
 {q:"Do you need 10,000 steps to benefit?", o:["Yes, exactly","No, benefits appear at lower counts","Only on weekends"], a:1, w:"Studies show strong benefits well below 10,000 steps."},
 {q:"Which symptom during exercise needs medical attention?", o:["Chest pain","Mild warmth","Light sweating"], a:0, w:"Chest pain, fainting or severe breathlessness are warning signs."}
]},
{ id:"he07", cat:"health", e:"🧘", title:"Mobility and Posture", sub:"Move freely, sit better, hurt less", cards:[
 {e:"🪑", h:"Best posture is the next one", t:"No single sitting position is perfect for hours. Your body is designed to move. Change position often, stand, walk and stretch rather than trying to hold a rigid upright pose."},
 {e:"⏲️", h:"Break up sitting", t:"Set a reminder to stand or move every 30 to 60 minutes. A minute or two is enough to reset. This helps circulation, stiffness and focus, and it costs almost no time.", stat:{n:"30-60 min", l:"common interval for a movement break"}},
 {e:"🖥️", h:"Set up your desk", t:"Put the top of your screen near eye level, keep elbows around 90 degrees, feet flat and wrists relaxed. Small adjustments reduce neck and shoulder strain, though movement matters more than the perfect setup.", list:["Screen top at eye level","Elbows near 90 degrees","Feet flat on floor","Keyboard close to the body"]},
 {e:"🔄", h:"Mobility versus flexibility", t:"Flexibility is how far a muscle can stretch passively. Mobility is controlled movement through a joint's range. Both help, but strengthening through your range tends to improve how movement feels day to day."},
 {e:"🐈", h:"Gentle spine movement", t:"Cat-cow, thoracic rotations and gentle hip circles lubricate joints and relieve stiffness. Move slowly and stay within comfortable range. Mild stretch is fine; sharp pain is a signal to stop."},
 {e:"🦵", h:"Open your hips", t:"Long sitting tightens hip flexors. A kneeling hip flexor stretch and deep bodyweight squat holds help maintain hip range. Hold stretches for 20 to 40 seconds and breathe normally."},
 {e:"💪", h:"Strengthen the back side", t:"Rows, glute bridges and exercises for the upper back support better posture more than constant stretching. A strong back and glutes help you hold positions comfortably with less effort."},
 {e:"🩺", h:"When to get checked", t:"Back or neck pain that persists, spreads down a limb, comes with numbness or weakness, or follows an injury should be assessed by a doctor or physiotherapist. Do not push through concerning symptoms."}
], quiz:[
 {q:"What is the best approach to posture?", o:["Hold one perfect position","Change positions often","Slouch all day"], a:1, w:"Frequent movement beats holding any single posture."},
 {q:"How often is a movement break commonly suggested?", o:["Every 30-60 minutes","Once a day","Once a week"], a:0, w:"Short breaks every half hour to hour reduce stiffness."},
 {q:"Which strengthening helps posture?", o:["Back and glute exercises","Only abs","Only stretching"], a:0, w:"Rows and glute work support upright, comfortable positions."},
 {q:"Which symptom deserves a professional check?", o:["Numbness or weakness in a limb","Mild morning stiffness","Feeling relaxed"], a:0, w:"Neurological symptoms need medical evaluation."}
]},
{ id:"he08", cat:"health", e:"🌬️", title:"Stress and Breathing", sub:"Calm your nervous system on demand", cards:[
 {e:"😮‍💨", h:"Stress is normal", t:"Short bursts of stress can help you perform. Long-lasting, unrelieved stress is linked with poor sleep, tension and lower mood. The goal is not zero stress but good recovery between demands."},
 {e:"🫁", h:"Slow your exhale", t:"Breathing slowly, especially with a longer out-breath, can shift your body toward a calmer state. Try inhaling for four counts and exhaling for six for a few minutes."},
 {e:"📦", h:"Box breathing", t:"Inhale four, hold four, exhale four, hold four. Repeat for one to three minutes. It gives your mind a simple task and is easy to do anywhere. If you feel lightheaded, return to normal breathing.", list:["Inhale 4 seconds","Hold 4 seconds","Exhale 4 seconds","Hold 4 seconds"]},
 {e:"🦁", h:"Physiological sigh", t:"Take a double inhale through the nose followed by a long exhale through the mouth. A few rounds can quickly ease tension in the moment. It is a handy tool before a hard conversation."},
 {e:"🌳", h:"Time in nature", t:"Spending time outdoors, even a 20-minute walk in a park, is linked with lower stress levels. Pair it with leaving your phone in your pocket for an even bigger reset.", stat:{n:"~20 min", l:"nature time linked with lower stress hormones in studies"}},
 {e:"📝", h:"Offload your mind", t:"Writing down worries and next steps gets them out of your head. A short evening brain dump or to-do list can reduce rumination and help you sleep. You do not need to solve everything, just capture it."},
 {e:"🤝", h:"Lean on people", t:"Social support is one of the strongest buffers against stress. A call, walk or honest chat with a friend often helps more than another hour of solo worrying."},
 {e:"🩺", h:"When stress is too much", t:"If stress or anxiety interferes with daily life, sleep or relationships for weeks, or you feel hopeless, speak with a doctor or mental health professional. In crisis, contact local emergency services or a crisis line."}
], quiz:[
 {q:"Which breathing pattern helps calm you?", o:["Fast shallow breaths","Longer exhale than inhale","Holding breath for minutes"], a:1, w:"Extending the exhale supports relaxation."},
 {q:"What is box breathing?", o:["4-4-4-4 counts","10-0-10-0 counts","1-1-1-1 counts"], a:0, w:"Equal four-second inhale, hold, exhale, hold."},
 {q:"What helps buffer stress strongly?", o:["Social support","Isolation","Skipping sleep"], a:0, w:"Connection with others is a strong stress buffer."},
 {q:"When should you seek professional help for stress?", o:["When it disrupts daily life for weeks","Never","Only after a year"], a:0, w:"Persistent impairment is a reason to talk to a professional."}
]},
{ id:"he09", cat:"health", e:"🧠", title:"Mental Health Habits", sub:"Small routines that support your mind", cards:[
 {e:"🌱", h:"Mind and body connect", t:"Sleep, movement, food, light and relationships all affect mood. Daily habits will not replace professional care when it is needed, but they give your mind a stronger foundation to work from."},
 {e:"🏃", h:"Move to feel better", t:"Regular physical activity is linked with lower symptoms of depression and anxiety in many studies. You do not need intense workouts; a brisk daily walk is a solid start.", stat:{n:"3x/week", l:"activity frequency often studied for mood benefits"}},
 {e:"🙏", h:"Practise gratitude", t:"Noting two or three specific things that went well each day can nudge attention toward the positive. Keep it brief and honest. Forced positivity is not the goal, noticing is."},
 {e:"📵", h:"Manage your scroll", t:"Heavy social media use can fuel comparison and poor sleep for some people. Notice how you feel after scrolling, mute accounts that drain you, and set phone-free windows such as meals or the first hour of the day."},
 {e:"🗓️", h:"Keep routines and goals", t:"Regular wake times, meals and small meaningful tasks give days structure, which helps when mood is low. Break big tasks into the smallest next step and celebrate finishing it."},
 {e:"💬", h:"Talk about it", t:"Sharing how you feel with someone you trust reduces isolation. Being specific helps, such as saying you have felt low for two weeks. You do not need to have a solution before you speak."},
 {e:"⚠️", h:"Know the signs", t:"Persistent low mood, loss of interest, major sleep or appetite changes, or intense worry lasting more than a couple of weeks are worth discussing with a doctor.", list:["Low mood most days","Loss of interest","Big sleep or appetite changes","Trouble functioning daily"]},
 {e:"🆘", h:"Getting help is strength", t:"Therapy and medical care are effective for many conditions. If you ever have thoughts of harming yourself, contact local emergency services or a crisis line right away. You do not have to manage it alone."}
], quiz:[
 {q:"Which is linked with improved mood in studies?", o:["Regular physical activity","Skipping sleep","Constant isolation"], a:0, w:"Regular movement is associated with reduced depression and anxiety symptoms."},
 {q:"What makes a gratitude practice useful?", o:["Being specific and honest","Making it long","Doing it only once"], a:0, w:"Brief, genuine, specific notes work best."},
 {q:"When should you speak to a doctor about mood?", o:["Symptoms lasting more than a couple of weeks","Never","Only after a crisis"], a:0, w:"Persistent symptoms deserve professional evaluation."},
 {q:"What should you do if you have thoughts of self-harm?", o:["Wait it out alone","Contact emergency services or a crisis line","Ignore it"], a:1, w:"Immediate professional support is the safest step."}
]},
{ id:"he10", cat:"health", e:"🦠", title:"Gut Health Basics", sub:"Feed the microbes, keep digestion happy", cards:[
 {e:"🔬", h:"Meet your microbiome", t:"Trillions of microbes live in your gut and help with digestion, immune function and more. Research is evolving fast, but diversity of diet is consistently linked with a healthier, more varied microbiome."},
 {e:"🌈", h:"Eat many plants", t:"Aim for variety across vegetables, fruit, legumes, whole grains, nuts and seeds. Some researchers suggest targeting around 30 different plant foods a week, counting herbs and spices.", stat:{n:"~30", l:"different plant foods per week is a popular target"}},
 {e:"🫘", h:"Fibre feeds good bacteria", t:"Gut microbes ferment fibre into compounds that support the gut lining. Increase fibre gradually and drink water, or you may get gas and bloating. Beans, oats, onions, bananas and berries are good starters."},
 {e:"🥛", h:"Fermented foods", t:"Yogurt with live cultures, kefir, kimchi, sauerkraut and miso can add beneficial microbes and have been linked with better microbiome diversity. Start with small servings and see how you feel."},
 {e:"💊", h:"Probiotics: be realistic", t:"Probiotic supplements can help in specific situations, but evidence varies by strain and condition, and they are not necessary for most healthy people. Food first, and ask a doctor or pharmacist before starting one."},
 {e:"🍔", h:"Limit ultra-processed", t:"Diets heavy in ultra-processed foods tend to be low in fibre and diverse nutrients. You do not have to avoid them entirely, but building most meals from whole ingredients supports your gut."},
 {e:"🧘", h:"Stress, sleep and gut", t:"Your gut and brain communicate constantly. Poor sleep and chronic stress can upset digestion for some people. Regular meals, movement and wind-down habits often help your stomach as well as your mind."},
 {e:"🚩", h:"See a doctor for red flags", t:"Do not self-diagnose digestive problems. See a doctor for blood in stools, unexplained weight loss, persistent pain, ongoing diarrhea or constipation, or trouble swallowing.", list:["Blood in stool","Unexplained weight loss","Persistent abdominal pain","Long-lasting bowel changes"]}
], quiz:[
 {q:"What does dietary variety support?", o:["A more diverse microbiome","Less sleep","Weaker digestion"], a:0, w:"Eating many different plants is linked to microbial diversity."},
 {q:"What should you do when increasing fibre?", o:["Go gradually and drink water","Do it all at once","Avoid water"], a:0, w:"Gradual increases reduce gas and bloating."},
 {q:"Are probiotic supplements necessary for most healthy people?", o:["Yes, daily","Not usually","They are dangerous for all"], a:1, w:"Evidence is mixed and food sources generally suffice."},
 {q:"Which is a red flag needing a doctor?", o:["Blood in stool","Mild gas after beans","Hunger before lunch"], a:0, w:"Bleeding warrants medical evaluation."}
]},
{ id:"he11", cat:"health", e:"🌞", title:"Sun, Vitamin D and Eyes", sub:"Light, skin and screen smarts", cards:[
 {e:"☀️", h:"Why sunlight helps", t:"Sunlight triggers vitamin D production in your skin and helps set your body clock and mood. Outdoor time also supports children's eye health. Balance benefits against skin cancer risk."},
 {e:"🦴", h:"Vitamin D basics", t:"Vitamin D supports bones and muscles. Needs depend on skin tone, location, season and diet. If you are worried about your level, ask a doctor about a blood test rather than guessing with high-dose supplements."},
 {e:"🧴", h:"Protect your skin", t:"Use broad-spectrum SPF 30 or higher, reapply every two hours outdoors, and wear hats and sunglasses. Seek shade around midday. Check moles regularly and see a doctor about any that change.", stat:{n:"SPF 30+", l:"commonly recommended broad-spectrum sunscreen"}},
 {e:"🕶️", h:"Protect your eyes", t:"Sunglasses labelled with UV400 or 100 percent UV protection shield your eyes from damaging rays. Wide-brimmed hats add extra defence. Never stare directly at the sun."},
 {e:"💻", h:"The 20-20-20 rule", t:"Every 20 minutes, look at something about 20 feet (6 metres) away for at least 20 seconds. This eases the focusing strain of near work and reminds you to blink.", stat:{n:"20-20-20", l:"minutes, feet, seconds eye-break rule"}},
 {e:"👀", h:"Blink and adjust", t:"We blink less when staring at screens, which dries eyes. Blink deliberately, keep the screen slightly below eye level, and reduce glare. Lubricating drops can help if you have dryness; ask a pharmacist."},
 {e:"🌃", h:"Lighting and brightness", t:"Match screen brightness to the room and avoid using a bright screen in a dark room. Larger text and good ambient lighting reduce squinting. Evening dimming may help wind down for sleep."},
 {e:"🩺", h:"Regular eye exams", t:"Get your eyes checked regularly, since many eye conditions have no early symptoms. See a professional promptly for sudden vision changes, flashes, floaters or eye pain.", list:["Routine exams as advised","Sudden vision loss: urgent","New flashes or floaters: urgent","Persistent eye pain or redness"]}
], quiz:[
 {q:"What does the 20-20-20 rule involve?", o:["Looking 20 feet away for 20 seconds every 20 minutes","Walking 20 miles","Sleeping 20 hours"], a:0, w:"It rests the eye's focusing muscles during near work."},
 {q:"What minimum sunscreen is commonly recommended?", o:["SPF 5","SPF 30 broad-spectrum","None needed"], a:1, w:"SPF 30 or higher with broad-spectrum coverage is the usual advice."},
 {q:"How should you check your vitamin D level?", o:["Guess and megadose","Ask a doctor about testing","Ignore it forever"], a:1, w:"Testing guides safe, appropriate decisions."},
 {q:"Which eye symptom is urgent?", o:["Sudden vision changes or flashes","Mild tiredness","Normal blinking"], a:0, w:"Sudden changes can signal serious problems needing prompt care."}
]},
{ id:"he12", cat:"health", e:"☕", title:"Caffeine and Alcohol", sub:"Use them wisely or skip them", cards:[
 {e:"☕", h:"Caffeine in moderation", t:"For most healthy adults, up to about 400 mg of caffeine daily, roughly four small cups of coffee, is considered generally safe. Sensitivity varies greatly, and pregnancy or heart conditions call for lower limits and medical advice.", stat:{n:"400 mg", l:"commonly cited upper daily caffeine limit for adults"}},
 {e:"🕓", h:"Timing is everything", t:"Caffeine blocks the chemical that builds sleep pressure. Cut it off six to eight hours before bed if sleep is an issue. Avoid using it to cover for chronic short sleep."},
 {e:"🤝", h:"Dependence is real", t:"Regular use can cause mild dependence, and stopping suddenly may bring headaches or fatigue for a few days. If you want to cut back, reduce gradually and swap in decaf or tea."},
 {e:"🍷", h:"No truly safe amount", t:"Recent evidence suggests that any alcohol carries some health risk, and the risk rises with the amount. Older claims of clear heart benefits have been challenged. If you do not drink, do not start for health reasons."},
 {e:"📊", h:"Know the guidelines", t:"Many guidelines suggest limiting to no more than about one drink a day for women and two for men, with several alcohol-free days. Less is better. Pregnant people should avoid alcohol entirely.", stat:{n:"1-2/day", l:"upper drinking limit in many national guidelines"}},
 {e:"😴", h:"Alcohol wrecks sleep", t:"Alcohol may make you drowsy but fragments sleep and suppresses REM sleep, leaving you less rested. Avoid drinking in the few hours before bed to protect your night."},
 {e:"🥂", h:"Drink more mindfully", t:"If you drink, make it intentional. Alternate with water, eat first, set a limit in advance and take regular alcohol-free days.", list:["Set a limit before you start","Alternate with water","Eat before and during","Plan alcohol-free days"]},
 {e:"🩺", h:"When to seek help", t:"If you cannot cut down despite trying, drink to cope with stress, or notice withdrawal symptoms, talk to a doctor. Help is available and effective. Stopping heavy drinking suddenly can be dangerous, so get medical guidance first."}
], quiz:[
 {q:"What is a commonly cited caffeine upper limit for adults?", o:["About 400 mg per day","About 40 mg","About 4,000 mg"], a:0, w:"Roughly four cups of coffee is the usual guidance."},
 {q:"How does alcohol affect sleep?", o:["It improves sleep quality","It fragments sleep and suppresses REM","It has no effect"], a:1, w:"It may cause drowsiness but worsens sleep quality."},
 {q:"What helps if you want to cut caffeine?", o:["Stop abruptly and endure headaches","Reduce gradually","Double the dose"], a:1, w:"Gradual reduction limits withdrawal symptoms."},
 {q:"Is there a proven health reason to start drinking alcohol?", o:["Yes, for heart health","No","Yes, for sleep"], a:1, w:"Current evidence does not support starting alcohol for health."}
]},
{ id:"he13", cat:"health", e:"⚖️", title:"Weight, Eating Out, Meal Prep", sub:"Sustainable habits over quick fixes", cards:[
 {e:"🎯", h:"Weight is more than numbers", t:"Weight is one health indicator among many. Waist size, fitness, blood pressure, sleep and energy matter too. Focus on habits you can sustain, and talk to a doctor about healthy goals for your body."},
 {e:"🔥", h:"Energy balance basics", t:"Weight change generally depends on long-run calories in versus out, but appetite, sleep, hormones and environment all influence both sides. Small, steady changes beat dramatic cuts that trigger rebound hunger."},
 {e:"🐢", h:"Slow and steady", t:"A gradual loss of about 0.25 to 0.5 kg (0.5 to 1 lb) a week is commonly considered sustainable. Crash diets often lead to muscle loss and regain. Avoid extreme restriction, and seek help if food feels stressful.", stat:{n:"0.25-0.5 kg", l:"weekly loss often seen as sustainable"}},
 {e:"🥣", h:"Fill up on volume", t:"Foods high in water, fibre and protein, such as vegetables, soups, beans, fruit and lean protein, fill you up on fewer calories. Start meals with a salad or soup if that works for you."},
 {e:"🍱", h:"Meal prep simply", t:"You do not need 21 identical boxes. Prep components: cook a batch of grains, roast vegetables, prepare a protein and keep sauces on hand. Mix and match through the week. Refrigerate cooked food promptly.", list:["Cook one grain","Roast a tray of vegetables","Prepare one or two proteins","Wash and chop fruit"]},
 {e:"🛒", h:"Shop with a list", t:"A list and a full stomach cut impulse buys. Fill your cart from the outer aisles first: produce, protein, dairy. Keep tempting snacks out of sight at home rather than relying on willpower."},
 {e:"🍽️", h:"Eating out wisely", t:"Check menus beforehand, choose grilled, baked or steamed dishes, ask for sauces on the side, and share starters or desserts. Portions are often large, so boxing half for later is a smart move."},
 {e:"🩺", h:"Get support when needed", t:"If you have a history of disordered eating, medical conditions or take medication, work with a doctor or dietitian before changing your diet. Weight-loss medicines and surgery are medical decisions for professionals."}
], quiz:[
 {q:"What pace of weight loss is commonly seen as sustainable?", o:["5 kg a week","0.25-0.5 kg a week","Losing nothing ever"], a:1, w:"Gradual loss is easier to maintain than crash dieting."},
 {q:"Which foods help you feel full on fewer calories?", o:["High-fibre, high-protein, high-water foods","Pastries","Sugary drinks"], a:0, w:"Volume, fibre and protein improve satiety."},
 {q:"What is a smart meal prep approach?", o:["Prep components to mix and match","Eat identical boxes forever","Skip refrigeration"], a:0, w:"Component prep keeps variety and flexibility."},
 {q:"Who should get professional guidance before changing diet?", o:["People with medical conditions or disordered eating history","Nobody","Only athletes"], a:0, w:"Medical context matters for safe changes."}
]},
{ id:"he14", cat:"health", e:"🦺", title:"Injury Prevention and Longevity", sub:"Stay capable for decades", cards:[
 {e:"🧗", h:"Longevity is built daily", t:"The strongest evidence points to not smoking, regular activity, healthy eating, good sleep, limited alcohol, strong relationships and routine health checks. No supplement or gadget beats these basics."},
 {e:"💪", h:"Fitness predicts lifespan", t:"Higher cardio fitness and muscle strength are strongly linked with lower risk of early death. Improving from low to moderate fitness delivers some of the biggest gains. Start where you are.", stat:{n:"Top predictor", l:"cardio fitness among long-term health markers"}},
 {e:"🧓", h:"Protect balance and strength", t:"Balance and leg strength help prevent falls as you age. Practise standing on one leg, sit-to-stand squats and walking on varied ground. Strong bones and muscles are worth building at every age."},
 {e:"📈", h:"Increase load gradually", t:"Most overuse injuries come from doing too much too soon. Increase running distance, weights or training time by modest steps, around 10 percent per week as a rough guide, and let recovery catch up."},
 {e:"🔥", h:"Warm up, cool down", t:"A brief warm-up prepares joints, muscles and your heart for work. Finish with easy movement and some stretching if it feels good. These steps are simple insurance against avoidable strains."},
 {e:"👟", h:"Listen to pain", t:"Mild muscle soreness is normal. Sharp, pinching, worsening or joint pain is not. Back off, adjust and rest. Persistent pain, swelling or loss of function deserves a check by a doctor or physiotherapist."},
 {e:"🛡️", h:"Use the right gear", t:"Wear supportive, well-fitting shoes, helmets for cycling and sports, and appropriate protective gear. Replace running shoes after several hundred miles as cushioning degrades.", list:["Helmet for cycling","Supportive shoes","Mouthguard for contact sport","Sun and hydration prep"]},
 {e:"🩺", h:"Do the checkups", t:"Prevention works best with routine screening such as blood pressure, cholesterol, vaccinations and age-appropriate cancer screening. Ask a doctor which checks you need, since recommendations depend on age and risk."}
], quiz:[
 {q:"Which factor is strongly linked with longer life?", o:["Higher cardio fitness","Skipping exercise","Chronic sleep loss"], a:0, w:"Fitness is one of the strongest predictors of longevity."},
 {q:"What is a common cause of overuse injury?", o:["Doing too much too soon","Resting too much","Warming up"], a:0, w:"Rapid increases in load outpace tissue adaptation."},
 {q:"Which pain should make you stop?", o:["Sharp or worsening pain","Mild muscle soreness","Feeling warm"], a:0, w:"Sharp or joint pain signals possible injury."},
 {q:"How do you know which health screenings you need?", o:["Ask a doctor","Guess","Skip them"], a:0, w:"Recommendations depend on age and personal risk."}
]},
{ id:"he15", cat:"health", e:"⚡", title:"Focus and Energy", sub:"Think clearly and feel less drained", cards:[
 {e:"🔋", h:"Energy is a system", t:"Energy comes from sleep, food, movement, light, hydration and recovery. Before reaching for a quick fix, check the basics. Most daytime slumps trace back to one of these."},
 {e:"🌅", h:"Start the day well", t:"A glass of water, daylight and some movement soon after waking helps you feel alert. Eat a breakfast with protein and fibre if you are hungry; skip it if you are not and feel fine."},
 {e:"🍚", h:"Beat the afternoon slump", t:"Large, refined-carb lunches can leave you drowsy. Build lunch around protein, vegetables and whole grains, then take a short walk. Natural dips in alertness after lunch are normal."},
 {e:"🍅", h:"Work in focused blocks", t:"Our attention fades with long stretches. Try 25 to 50 minutes of focus followed by a 5 to 10 minute break. Silence notifications and work on one thing at a time.", stat:{n:"25-50 min", l:"common focus block length before a break"}},
 {e:"📵", h:"Cut interruptions", t:"Task switching has a real cost: it takes time to regain focus after each interruption. Put your phone in another room, close extra tabs and batch email to a few set times."},
 {e:"🚶", h:"Move to refresh", t:"A short walk or a few minutes of light movement can boost alertness and mood. Breaks away from your screen often refresh you better than scrolling."},
 {e:"😴", h:"Mind the short nap", t:"A 10 to 20 minute nap early in the afternoon can lift alertness for many people. Longer or later naps may cause grogginess or disturb night sleep.", list:["Nap 10-20 minutes","Before about 3 pm","Dark, quiet spot","Set an alarm"]},
 {e:"🩺", h:"Persistent fatigue", t:"Everyone has tired days. If you feel constantly exhausted despite good sleep, or notice fatigue with weight changes, low mood or other symptoms, see a doctor. Causes like anaemia or thyroid problems are common and testable."}
], quiz:[
 {q:"What often causes an afternoon slump?", o:["A big refined-carb lunch plus natural dips","Drinking water","Walking"], a:0, w:"Meal composition and the body's natural rhythm both play roles."},
 {q:"How long should an energising nap be?", o:["10-20 minutes","3 hours","None at all"], a:0, w:"Short naps boost alertness without grogginess."},
 {q:"What reduces focus costs most?", o:["Fewer interruptions","More tabs open","Constant notifications"], a:0, w:"Task switching drains attention and time."},
 {q:"When should persistent fatigue be checked?", o:["When it lasts despite good sleep","Never","Only when you feel great"], a:0, w:"Ongoing fatigue can have treatable medical causes."}
]},
{ id:"he16", cat:"health", e:"🔍", title:"Health Myths Debunked", sub:"Separate popular claims from evidence", cards:[
 {e:"🧐", h:"Why myths stick", t:"Health myths spread because they are simple, repeated and often contain a grain of truth. A good habit is to ask who is making the claim, what the evidence is, and whether it has been replicated."},
 {e:"🌙", h:"Myth: eating late makes you fat", t:"What matters most is total intake and quality across the day, not the clock. Late-night snacking can add calories and disturb sleep for some people, but food does not magically turn to fat after 8 pm."},
 {e:"🧂", h:"Myth: detox diets cleanse you", t:"Your liver, kidneys and gut already handle waste continuously. There is no strong evidence that juice cleanses or detox teas remove toxins better. Extreme versions can be risky. Eat plants and drink water instead."},
 {e:"🥩", h:"Myth: more protein is always better", t:"Protein matters, but beyond your needs extra does not build more muscle. Total diet, training and sleep drive results. Balance protein with plenty of fibre and plants."},
 {e:"🏃", h:"Myth: cracking joints causes arthritis", t:"Studies have not found that knuckle cracking leads to arthritis. Painful or swollen joints are another matter and deserve medical attention. Occasional harmless popping is common."},
 {e:"🍞", h:"Myth: carbs are bad", t:"Carbohydrates are your body's preferred fuel. Whole grains, fruit, legumes and vegetables are linked with good health. The issue is mostly large amounts of refined carbs and added sugar, not carbs themselves."},
 {e:"🏋️", h:"Myth: spot reduction", t:"Doing endless crunches will not burn belly fat specifically. Your body loses fat across the whole body based on genetics and overall energy balance. Strength training and cardio build a healthier body overall."},
 {e:"✅", h:"Check before you trust", t:"Be wary of miracle cures, instant results and anyone selling a product alongside the claim. Check reputable sources and ask a doctor or pharmacist before trying something new, especially with existing conditions or medication.", list:["Who benefits from the claim?","Is there strong evidence?","Is it too good to be true?","Ask a health professional"]}
], quiz:[
 {q:"Does eating after 8 pm automatically cause fat gain?", o:["Yes","No, total intake matters most","Only fruit does"], a:1, w:"Overall calories and quality matter more than timing."},
 {q:"Do detox teas outperform your liver and kidneys?", o:["No strong evidence they do","Yes, clearly","Only if expensive"], a:0, w:"Your organs already detoxify continuously."},
 {q:"Does doing crunches burn belly fat specifically?", o:["Yes","No, spot reduction is a myth","Only with a belt"], a:1, w:"Fat loss occurs across the body."},
 {q:"What is a good habit with a surprising health claim?", o:["Check the evidence and ask a professional","Share it instantly","Buy the product"], a:0, w:"Verification protects you from misinformation."}
]}
);
window.TIPS.push(
{cat:"health", e:"🌅", h:"Morning light first", t:"Get outside within an hour of waking. Daylight sets your body clock and makes falling asleep easier that night."},
{cat:"health", e:"🛏️", h:"Same wake time daily", t:"A steady wake time, even on weekends, does more for your sleep than chasing extra hours on random days."},
{cat:"health", e:"📵", h:"Phone out of bed", t:"Charge your phone across the room. It removes the temptation to scroll and protects your first and last minutes of the day."},
{cat:"health", e:"☕", h:"Coffee cutoff", t:"If sleep is poor, try stopping caffeine eight hours before bedtime. Many people notice a difference within days."},
{cat:"health", e:"🥦", h:"Half-plate produce", t:"Fill roughly half your plate with vegetables or fruit. It boosts fibre and nutrients without counting anything."},
{cat:"health", e:"🌾", h:"Fibre first", t:"Add one fibre-rich food to each meal, like beans, oats or berries. Increase slowly and drink water as you go."},
{cat:"health", e:"🏷️", h:"Per-100g comparison", t:"Compare nutrition labels per 100 g, not per serving. It makes sugar, salt and fibre differences between products obvious."},
{cat:"health", e:"🍳", h:"Protein at breakfast", t:"Eggs, yogurt or tofu in the morning can keep hunger steadier than a sugary start. Try it for a week."},
{cat:"health", e:"🧮", h:"Protein baseline", t:"Healthy adults need at least 0.8 g protein per kg of body weight daily. Active people often aim higher."},
{cat:"health", e:"💧", h:"Check your pee", t:"Pale straw yellow is a decent sign of good hydration. Dark amber means drink a bit more."},
{cat:"health", e:"🚰", h:"Water by your side", t:"A bottle within sight beats willpower. People drink more when water is easy to reach."},
{cat:"health", e:"🍋", h:"Flavour your water", t:"Bored of plain water? Add lemon, cucumber or mint. Anything that helps you sip more is a win."},
{cat:"health", e:"🏋️", h:"Lift twice a week", t:"Two short strength sessions weekly support muscle, bones and balance. Start light and master form first."},
{cat:"health", e:"📈", h:"Add one rep", t:"Progress in strength can be as simple as one more rep or a tiny weight jump each week or two."},
{cat:"health", e:"🔁", h:"Master the basics", t:"Squat, hinge, push, pull and carry cover most of what you need. Learn them well before adding extras."},
{cat:"health", e:"🛌", h:"Muscle grows at rest", t:"Training breaks muscle down; sleep, food and rest rebuild it. Skipping recovery stalls progress."},
{cat:"health", e:"🚶", h:"Walk after meals", t:"A 10-minute stroll after eating helps digestion and blunts blood sugar spikes. It is the easiest habit to add."},
{cat:"health", e:"🗣️", h:"The talk test", t:"If you can talk but not sing, you are at moderate intensity. No gadget needed to check effort."},
{cat:"health", e:"👣", h:"Steps beat perfection", t:"Benefits from walking start well below 10,000 steps. Aim to beat your own average first."},
{cat:"health", e:"⏲️", h:"Stand every hour", t:"Set a timer to stand or stroll for a minute or two each hour. Your back, mood and focus will thank you."},
{cat:"health", e:"🪑", h:"Best posture is the next", t:"No position is perfect for hours. Change posture often instead of hunting for the ideal one."},
{cat:"health", e:"🖥️", h:"Eye-level screen", t:"Raise your screen so the top sits near eye level. It reduces neck strain during long work sessions."},
{cat:"health", e:"🐈", h:"Two-minute spine reset", t:"Try cat-cow and gentle trunk rotations to loosen a stiff back. Move slowly and stop at any sharp pain."},
{cat:"health", e:"🌬️", h:"Longer exhale", t:"Breathe in for four, out for six. A longer exhale nudges your body toward calm in just a few minutes."},
{cat:"health", e:"📦", h:"Box breathing", t:"Inhale four, hold four, exhale four, hold four. It gives a racing mind a simple job to do."},
{cat:"health", e:"🌳", h:"Twenty minutes outside", t:"A short park walk is linked with lower stress. Leave your phone in your pocket for a bigger reset."},
{cat:"health", e:"📝", h:"Brain dump at night", t:"Write down worries and tomorrow's tasks before bed. Getting them on paper can quiet a busy mind."},
{cat:"health", e:"🤝", h:"Reach out", t:"A call or walk with a friend often helps more than hours of solo worrying. Connection buffers stress."},
{cat:"health", e:"🙏", h:"Name three good things", t:"Noting a few specific good moments each day gently trains attention toward what is working."},
{cat:"health", e:"🆘", h:"Ask for help early", t:"Low mood or anxiety lasting weeks deserves a conversation with a doctor. Getting support is a strength."},
{cat:"health", e:"🌈", h:"Eat the rainbow", t:"Different coloured plants bring different nutrients and feed different gut microbes. Variety is the goal."},
{cat:"health", e:"🥛", h:"Try fermented foods", t:"Yogurt with live cultures, kefir or kimchi can support gut diversity. Start with small servings."},
{cat:"health", e:"🧴", h:"SPF 30 daily", t:"Broad-spectrum SPF 30 or higher on exposed skin, reapplied every two hours outdoors, protects against skin damage."},
{cat:"health", e:"🕶️", h:"UV400 shades", t:"Choose sunglasses with full UV protection. Your eyes need defence from sunlight just like your skin."},
{cat:"health", e:"👀", h:"20-20-20 rule", t:"Every 20 minutes look at something 20 feet away for 20 seconds. Your eyes get a needed break."},
{cat:"health", e:"😌", h:"Blink more", t:"We blink less at screens, drying our eyes. Blink on purpose and look away often."},
{cat:"health", e:"🦴", h:"Test, don't guess", t:"Worried about vitamin D? Ask a doctor about a blood test before taking high-dose supplements."},
{cat:"health", e:"🍷", h:"Less is better", t:"Current evidence says no amount of alcohol is risk-free. If you drink, keep it low and take alcohol-free days."},
{cat:"health", e:"💦", h:"Water between drinks", t:"Alternate alcoholic drinks with water. You will drink less and feel better the next morning."},
{cat:"health", e:"🌙", h:"Alcohol and sleep", t:"Alcohol can make you drowsy but fragments sleep. Skip it in the last few hours before bed."},
{cat:"health", e:"🍽️", h:"Eat slowly", t:"Slowing down gives fullness signals time to arrive. Put your fork down between bites sometimes."},
{cat:"health", e:"🛒", h:"List and full stomach", t:"Shop with a list and after a meal. Impulse buys drop sharply when you are not hungry."},
{cat:"health", e:"🍱", h:"Prep components", t:"Cook a grain, roast vegetables and prepare a protein on one day. Mix and match all week."},
{cat:"health", e:"🍴", h:"Share at restaurants", t:"Portions are often huge. Share a starter or box half your meal for tomorrow's lunch."},
{cat:"health", e:"🐢", h:"Slow and steady", t:"Gradual weight change of about half a kilo a week is easier to maintain than crash diets."},
{cat:"health", e:"🔥", h:"Warm up first", t:"Five minutes of light movement before exercise preps joints and muscles and lowers injury risk."},
{cat:"health", e:"📏", h:"Add load slowly", t:"Increase training volume in small steps. Most overuse injuries come from doing too much, too soon."},
{cat:"health", e:"⚠️", h:"Sharp pain means stop", t:"Mild soreness is normal; sharp or worsening pain is not. Back off and get checked if it persists."},
{cat:"health", e:"🧍", h:"Practise one-leg stands", t:"Stand on one leg while brushing your teeth. Balance training helps prevent falls as you age."},
{cat:"health", e:"❤️", h:"Fitness lengthens life", t:"Better cardio fitness and strength are strongly linked with longer, healthier lives. Any improvement counts."},
{cat:"health", e:"🩺", h:"Do your checkups", t:"Ask your doctor which screenings you need. Early detection and prevention work best when routine."},
{cat:"health", e:"🍅", h:"Focus in blocks", t:"Work 25 to 50 minutes on one thing, then take a short break. Silence notifications during the block."},
{cat:"health", e:"😴", h:"Short nap rule", t:"A 10 to 20 minute early-afternoon nap can lift alertness. Longer or later naps often backfire."},
{cat:"health", e:"🚭", h:"Skip smoking", t:"Not smoking is among the biggest things you can do for your health. Ask a doctor about quit support."},
{cat:"health", e:"🌙", h:"Eating late myth", t:"Food does not magically turn to fat after 8 pm. Total intake and quality across the day matter most."},
{cat:"health", e:"🧃", h:"Detox myth", t:"Your liver and kidneys already detox continuously. Detox teas and cleanses have little evidence behind them."},
{cat:"health", e:"🎯", h:"Spot reduction myth", t:"Crunches will not burn belly fat specifically. Fat loss happens across the whole body."},
{cat:"health", e:"🧂", h:"Cook more, salt less", t:"Most salt comes from packaged and restaurant food. Cooking at home gives you control over how much goes in."},
{cat:"health", e:"🦷", h:"Floss and brush", t:"Brush twice daily and clean between teeth. Oral health is linked with overall health, and prevention is cheaper than fillings."},
{cat:"health", e:"🔍", h:"Question miracle claims", t:"If a health claim sounds too good to be true or comes with a product to buy, check the evidence and ask a professional."}
);
